 "CHECK_BEFORE_COMPRESSING": "PERIKSA_SEBELUM_MENGOMPRES",
 "CHECK_BEFORE_CONVERTING": "PERIKSA_SEBELUM_MENGONVERSI",
 "CHECK_BEFORE_STRIPPING": "PERIKSA_SEBELUM_MENGHAPUS",
